window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-99bfd1618c8c6532"]={"versions": [{"id": "FIG-99bfd1618c8c6532", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR-Hardware-Metamodells im Kontext des ECU-Ressourcen-Templates (<code>AUTOSAR_ResourceTemplateECU</code>). Das Diagramm modelliert die strukturellen Hardware-Verbindungselemente und deren Kapselung innerhalb hierarchischer Hardware-Element-Container.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>HWElement</code> (Spezialisierung von <code>ARElement</code>): Basisklasse für Hardware-Elemente mit dem Attribut <code>+ standbyCurrent: Float [0..1]</code>. Komposition von 1..* <code>HWPort</code> (<code>+ports</code>).\n</li><li><code>HWElementContainer</code> (abstrakte Spezialisierung von <code>HWElement</code>): Enthält kompositionell 1..* <code>HWElement</code> (<code>+containedElements</code>) sowie 0..* <code>HWConnection</code> (<code>+connections</code>).\n</li><li><code>HWContainer</code>: Konkrete Spezialisierung von <code>HWElementContainer</code>.\n</li><li><code>HWConnection</code> (Spezialisierung von <code>Identifiable</code>, abstrakt): Basisklasse für Hardware-Verbindungen. Komposition von 0..* <code>PinHWConnection</code> (<code>+connectedPins</code>).\n</li><li><code>AssemblyHWConnection</code> (Spezialisierung von <code>HWConnection</code>): Verbindet 2..* <code>HWPort</code> (<code>+hwPort</code>).\n</li><li><code>DelegationHWConnection</code> (Spezialisierung von <code>HWConnection</code>): Verbindet genau einen äußeren Port (<code>+OUTER-PORT: 1</code>) mit genau einem inneren Port (<code>+INNER-PORT: 1</code>) vom Typ <code>HWPort</code>.\n</li><li><code>HWPort</code> (Spezialisierung von <code>Identifiable</code>): Repräsentiert Hardware-Ports mit dem Attribut <code>+ direction: Enumeration{in, out, inout}</code>. Komposition von beliebigen <code>HWPin</code> (<code>+pins: *</code>).\n</li><li><code>HWPin</code> (Spezialisierung von <code>Identifiable</code>): Repräsentiert physische Hardware-Pins.\n</li><li><code>PinHWConnection</code>: Assoziiert 1..2 <code>HWPin</code> (<code>+connectedPin</code>). Multiplizität an <code>PinHWConnection</code> ist 1.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm stellt eine rein statische Metamodellstruktur dar. Es definiert keine dynamischen Sequenzen oder Zustandsübergänge, sondern legt die strukturelle Kompositions- und Verknüpfungshierarchie für Hardware-Topologien zur Entwurfs- und Konfigurationszeit fest.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Metamodell-Regeln für die Hardware-Topologiebeschreibung:</p>\n<ul class=\"fig-list\"><li>Hardware-Container aggregieren Sub-Hardware-Elemente sowie Verbindungen auf System- oder ECU-Ebene.\n</li><li>Verbindungen zwischen Ports auf gleicher Hierarchieebene erfordern <code>AssemblyHWConnection</code> (mindestens zwei Ports).\n</li><li>Hierarchieübergreifende Port-Verbindungen zwischen einem Container und seinen Unterelementen erfordern <code>DelegationHWConnection</code> mit jeweils genau einem äußeren (<code>+OUTER-PORT</code>) und einem inneren (<code>+INNER-PORT</code>).\n</li><li>Detaillierte Pin-Verbindungen werden über <code>PinHWConnection</code> modelliert, die 1 bis 2 Pins referenzieren können.\n</li><li>Port-Richtung ist durch die Enumeration <code>{in, out, inout}</code> typisiert.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-ced6dfc9e4e4373e", "releases": ["R3.0.7", "R3.1.5", "R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des AUTOSAR-Hardware-Metamodells im Kontext des ECU-Ressourcen-Templates (<code>AUTOSAR_ResourceTemplateECU</code>). Das Diagramm modelliert die strukturellen Hardware-Verbindungselemente und deren Kapselung innerhalb hierarchischer Hardware-Element-Container.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><code>HWElement</code> (Spezialisierung von <code>ARElement</code>): Basisklasse für Hardware-Elemente mit dem Attribut <code>+ standbyCurrent: Float [0..1]</code>. Komposition von 1..* <code>HWPort</code> (<code>+ports</code>).\n</li><li><code>HWElementContainer</code> (abstrakte Spezialisierung von <code>HWElement</code>): Enthält kompositionell 1..* <code>HWElement</code> (<code>+containedElements</code>) sowie 0..* <code>HWConnection</code> (<code>+connections</code>).\n</li><li><code>HWContainer</code>: Konkrete Spezialisierung von <code>HWElementContainer</code>.\n</li><li><code>HWConnection</code> (Spezialisierung von <code>Identifiable</code>, abstrakt): Basisklasse für Hardware-Verbindungen. Komposition von 0..* <code>PinHWConnection</code> (<code>+connectedPins</code>).\n</li><li><code>AssemblyHWConnection</code> (Spezialisierung von <code>HWConnection</code>): Verbindet 2..* <code>HWPort</code> (<code>+hwPort</code>).\n</li><li><code>DelegationHWConnection</code> (Spezialisierung von <code>HWConnection</code>): Verbindet genau einen äußeren Port (<code>+OUTER-PORT: 1</code>) mit genau einem inneren Port (<code>+INNER-PORT: 1</code>) vom Typ <code>HWPort</code>.\n</li><li><code>HWPort</code> (Spezialisierung von <code>Identifiable</code>): Repräsentiert Hardware-Ports mit dem Attribut <code>+ direction: Enumeration{in, out, inout}</code>. Komposition von beliebigen <code>HWPin</code> (<code>+pins: *</code>).\n</li><li><code>HWPin</code> (Spezialisierung von <code>Identifiable</code>): Repräsentiert physische Hardware-Pins.\n</li><li><code>PinHWConnection</code>: Assoziiert 1..2 <code>HWPin</code> (<code>+connectedPin</code>). Multiplizität an <code>PinHWConnection</code> ist 1.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm stellt eine rein statische Metamodellstruktur dar. Es definiert keine dynamischen Sequenzen oder Zustandsübergänge, sondern legt die strukturelle Kompositions- und Verknüpfungshierarchie für Hardware-Topologien zur Entwurfs- und Konfigurationszeit fest.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Metamodell-Regeln für die Hardware-Topologiebeschreibung:</p>\n<ul class=\"fig-list\"><li>Hardware-Container aggregieren Sub-Hardware-Elemente sowie Verbindungen auf System- oder ECU-Ebene.\n</li><li>Verbindungen zwischen Ports auf gleicher Hierarchieebene erfordern <code>AssemblyHWConnection</code> (mindestens zwei Ports).\n</li><li>Hierarchieübergreifende Port-Verbindungen zwischen einem Container und seinen Unterelementen erfordern <code>DelegationHWConnection</code> mit jeweils genau einem äußeren (<code>+OUTER-PORT</code>) und einem inneren (<code>+INNER-PORT</code>).\n</li><li>Detaillierte Pin-Verbindungen werden über <code>PinHWConnection</code> modelliert, die 1 bis 2 Pins referenzieren können.\n</li><li>Port-Richtung ist durch die Enumeration <code>{in, out, inout}</code> typisiert.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-99bfd1618c8c6532", "to": "FIG-ced6dfc9e4e4373e", "fr": "R2.1.20", "tr": "R3.0.7", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Layout / Bildausschnitt: Unterer Rand leicht beschnitten (die Klasse <code>AssemblyHWConnection</code> ist unten angeschnitten).\n</li><li>Keine semantischen oder normativen Änderungen an Modellelementen, Attributen oder Assoziationen erkennbar.\n</li></ul>"}]};
